import pathlib
H = pathlib.Path(__file__).resolve().parent
p = H / 'assets_jb.js'; t = p.read_text(encoding='utf8'); assert 'const boardDiagram' not in t
add = r'''  // ===== BOARD DIAGRAMS (2D): explain a deal on a sheet of paper / board. docs/JC_DEPICTION_MAP.md: buy/sell, borrow, invest, guarantee = nodes + arrows + things TRAVELLING along them on the spoken word =====
  const bdIcon = (g, k, cx, cy, s, col) => {
    g.save(); g.translate(cx, cy); g.lineJoin = 'round'; g.lineCap = 'round'; g.lineWidth = s * 0.11; g.strokeStyle = '#17252B'; const R = (x, y, w, h, r, f) => { rrect(g, x, y, w, h, r); if (f) { g.fillStyle = f; g.fill(); } g.stroke(); };
    if (k === 'bank') { g.beginPath(); g.moveTo(-s, -0.25 * s); g.lineTo(0, -s); g.lineTo(s, -0.25 * s); g.closePath(); g.fillStyle = '#E2B857'; g.fill(); g.stroke(); for (let i = -1; i <= 1; i++) R(i * 0.6 * s - 0.13 * s, -0.15 * s, 0.26 * s, 0.85 * s, 2, '#F7F4EC'); R(-s, 0.7 * s, 2 * s, 0.25 * s, 2, '#C9B98A'); }
    else if (k === 'company' || k === 'nvidia') { R(-0.7 * s, -s, 1.4 * s, 1.95 * s, 4, k === 'nvidia' ? '#1B2A31' : '#9FB3BD'); if (k === 'nvidia') { g.fillStyle = '#76B900'; g.fillRect(-0.7 * s, -s, 1.4 * s, 0.32 * s); } for (let r = 0; r < 3; r++) for (let c = 0; c < 2; c++) { g.fillStyle = '#F4F1EA'; g.fillRect(-0.45 * s + c * 0.55 * s, -0.4 * s + r * 0.45 * s, 0.35 * s, 0.26 * s); } }
    else if (k === 'cloud') { g.beginPath(); g.arc(-0.45 * s, 0.1 * s, 0.5 * s, 1.5, 4.6); g.arc(0.05 * s, -0.35 * s, 0.6 * s, 3.3, 6.0); g.arc(0.6 * s, 0.1 * s, 0.5 * s, 4.7, 1.6); g.closePath(); g.fillStyle = '#CFE3EA'; g.fill(); g.stroke(); R(-0.35 * s, 0.05 * s, 0.7 * s, 0.7 * s, 3, '#1B2A31'); g.fillStyle = '#76B900'; g.fillRect(-0.2 * s, 0.22 * s, 0.4 * s, 0.1 * s); g.fillRect(-0.2 * s, 0.45 * s, 0.4 * s, 0.1 * s); }
    else if (k === 'chip') { R(-0.6 * s, -0.6 * s, 1.2 * s, 1.2 * s, 4, '#76B900'); g.fillStyle = '#1B2A31'; g.fillRect(-0.28 * s, -0.28 * s, 0.56 * s, 0.56 * s); for (let i = -1; i <= 1; i++) { g.beginPath(); g.moveTo(i * 0.35 * s, -0.6 * s); g.lineTo(i * 0.35 * s, -0.85 * s); g.moveTo(i * 0.35 * s, 0.6 * s); g.lineTo(i * 0.35 * s, 0.85 * s); g.stroke(); } }
    else if (k === 'bag') { g.beginPath(); g.moveTo(-0.3 * s, -0.55 * s); g.quadraticCurveTo(0, -0.95 * s, 0.3 * s, -0.55 * s); g.stroke(); g.beginPath(); g.moveTo(-0.3 * s, -0.55 * s); g.quadraticCurveTo(-0.95 * s, 0.1 * s, -0.7 * s, 0.7 * s); g.lineTo(0.7 * s, 0.7 * s); g.quadraticCurveTo(0.95 * s, 0.1 * s, 0.3 * s, -0.55 * s); g.closePath(); g.fillStyle = '#E2B857'; g.fill(); g.stroke(); g.fillStyle = '#17252B'; g.font = '900 ' + s * 0.8 + 'px' + FAM; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('$', 0, 0.12 * s); }
    else if (k === 'coin') { g.beginPath(); g.arc(0, 0, 0.7 * s, 0, 7); g.fillStyle = '#E2B857'; g.fill(); g.stroke(); g.fillStyle = '#17252B'; g.font = '900 ' + s * 0.9 + 'px' + FAM; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText('$', 0, 0.05 * s); }
    else if (k === 'paper') { R(-0.55 * s, -0.8 * s, 1.1 * s, 1.6 * s, 3, '#FBF8EF'); g.lineWidth = s * 0.07; g.strokeStyle = '#8A97A2'; for (let i = 0; i < 3; i++) { g.beginPath(); g.moveTo(-0.35 * s, -0.5 * s + i * 0.28 * s); g.lineTo(0.35 * s, -0.5 * s + i * 0.28 * s); g.stroke(); } g.beginPath(); g.arc(0.25 * s, 0.45 * s, 0.2 * s, 0, 7); g.fillStyle = '#D64545'; g.fill(); }
    else if (k === 'racks') { for (let i = 0; i < 3; i++) { R(-1.05 * s + i * 0.75 * s, -0.8 * s, 0.6 * s, 1.6 * s, 3, col || '#2A3A44'); g.fillStyle = col ? '#E8FFF3' : '#4A5A64'; for (let j = 0; j < 3; j++) g.fillRect(-0.9 * s + i * 0.75 * s, -0.5 * s + j * 0.45 * s, 0.3 * s, 0.14 * s); } }
    else if (k === 'cal') { R(-0.8 * s, -0.7 * s, 1.6 * s, 1.5 * s, 4, '#FBF8EF'); g.fillStyle = '#D64545'; g.fillRect(-0.8 * s, -0.7 * s, 1.6 * s, 0.4 * s); g.fillStyle = '#C9D3D9'; for (let r = 0; r < 2; r++) for (let c = 0; c < 4; c++) g.fillRect(-0.62 * s + c * 0.4 * s, -0.12 * s + r * 0.4 * s, 0.26 * s, 0.26 * s); }
    else if (k === 'shield') { g.beginPath(); g.moveTo(0, -s); g.lineTo(0.8 * s, -0.7 * s); g.quadraticCurveTo(0.8 * s, 0.5 * s, 0, s); g.quadraticCurveTo(-0.8 * s, 0.5 * s, -0.8 * s, -0.7 * s); g.closePath(); g.fillStyle = '#76B900'; g.fill(); g.stroke(); }
    else if (k === 'hand') { g.fillStyle = '#F1C9A0'; R(-1.0 * s, -0.25 * s, 1.15 * s, 0.5 * s, 8, '#F1C9A0'); R(-0.15 * s, -0.25 * s, 1.15 * s, 0.5 * s, 8, '#E5B98E'); g.fillStyle = '#17252B'; g.fillRect(-1.2 * s, -0.3 * s, 0.25 * s, 0.6 * s); g.fillRect(0.95 * s, -0.3 * s, 0.25 * s, 0.6 * s); }
    else if (k === 'eye') { g.beginPath(); g.moveTo(-s, 0); g.quadraticCurveTo(0, -0.9 * s, s, 0); g.quadraticCurveTo(0, 0.9 * s, -s, 0); g.closePath(); g.fillStyle = '#FFFFFF'; g.fill(); g.stroke(); g.beginPath(); g.arc(0, 0, 0.32 * s, 0, 7); g.fillStyle = '#2C5BA8'; g.fill(); }
    g.restore();
  };
  // boardDiagram(g, pw, ph, spec, t): spec = { title, nodes:[{id, label, ico, x, y (0..1), t0, col, badge:[[time,'text'],...], eye:[t0,t1], lit:time, grow:[t0,t1]}],
  //   links:[{a, b, t0, kind:'bag'|'chip'|'paper'|'coin', label, col, off (perpendicular offset -1..1), curve}] }. Arrows draw on from t0 (0.6 s), then the item travels along them (loop) and the label pops. Everything appears on its own time.
  const boardDiagram = (g, pw, ph, S, t) => {
    const m = pw * 0.03; g.save(); g.shadowColor = 'rgba(11,25,30,0.38)'; g.shadowBlur = pw * 0.035; g.shadowOffsetY = pw * 0.014; rrect(g, m, m, pw - 2 * m, ph - 2 * m, ph * 0.02); g.fillStyle = '#FBF8EF'; g.fill(); g.restore();
    g.save(); rrect(g, m, m, pw - 2 * m, ph - 2 * m, ph * 0.02); g.clip(); g.strokeStyle = 'rgba(120,160,190,0.2)'; g.lineWidth = 1.5; for (let x = m; x < pw; x += ph * 0.05) { g.beginPath(); g.moveTo(x, m); g.lineTo(x, ph); g.stroke(); } for (let y = m; y < ph; y += ph * 0.05) { g.beginPath(); g.moveTo(m, y); g.lineTo(pw, y); g.stroke(); } g.restore();
    if (S.title) { g.fillStyle = '#17252B'; g.textAlign = 'left'; g.textBaseline = 'alphabetic'; g.font = '900 ' + ph * 0.065 + 'px' + FAM; g.fillText(S.title, pw * 0.06, ph * 0.13); }
    const A = { x0: pw * 0.06, x1: pw * 0.94, y0: ph * 0.2, y1: ph * 0.9 }, NW = pw * 0.2, NH = ph * 0.34, P = n => [A.x0 + (A.x1 - A.x0) * n.x, A.y0 + (A.y1 - A.y0) * n.y], by = {}; S.nodes.forEach(n => by[n.id] = n);
    (S.links || []).forEach(l => {
      const u = seg(t, l.t0, l.t0 + 0.6); if (u <= 0) return; const a = P(by[l.a]), b = P(by[l.b]), dx = b[0] - a[0], dy = b[1] - a[1], L = Math.hypot(dx, dy), ux = dx / L, uy = dy / L, nx = -uy, ny = ux, off = (l.off || 0) * ph * 0.06;
      const pad = (Math.abs(ux) > Math.abs(uy) ? NW / 2 + pw * 0.012 : NH / 2 + ph * 0.012), sx = a[0] + ux * pad + nx * off, sy = a[1] + uy * pad + ny * off, ex = b[0] - ux * pad + nx * off, ey = b[1] - uy * pad + ny * off, cx = sx + (ex - sx) * u, cy = sy + (ey - sy) * u, col = l.col || '#17252B';
      g.strokeStyle = col; g.fillStyle = col; g.lineWidth = ph * 0.014; g.lineCap = 'round'; g.beginPath(); g.moveTo(sx, sy); g.lineTo(cx, cy); g.stroke();
      if (u > 0.95) { const hs = ph * 0.04; g.beginPath(); g.moveTo(ex, ey); g.lineTo(ex - ux * hs + nx * hs * 0.6, ey - uy * hs + ny * hs * 0.6); g.lineTo(ex - ux * hs - nx * hs * 0.6, ey - uy * hs - ny * hs * 0.6); g.closePath(); g.fill(); }
      if (u >= 1) { const n = 2, tk = (t - l.t0 - 0.6) * 0.45; for (let k = 0; k < n; k++) { const q = (tk + k / n) % 1, px = sx + (ex - sx) * q, py = sy + (ey - sy) * q - Math.sin(q * Math.PI) * ph * 0.03; g.fillStyle = '#FBF8EF'; g.beginPath(); g.arc(px, py, ph * 0.062, 0, 7); g.fill(); bdIcon(g, l.kind || 'bag', px, py, ph * 0.05); } }
      if (l.label && u > 0.6) { const w = seg(t, l.t0 + 0.3, l.t0 + 0.7), mx = (sx + ex) / 2, my = (sy + ey) / 2 + (l.lab || 0) * ph * 0.095; g.save(); g.translate(mx, my); g.scale(0.7 + 0.3 * w, 0.7 + 0.3 * w); g.globalAlpha = w; g.font = '900 ' + ph * 0.05 + 'px' + FAM; const tw = g.measureText(l.label).width + ph * 0.1; rrect(g, -tw / 2, -ph * 0.04, tw, ph * 0.08, ph * 0.03); g.fillStyle = col; g.fill(); g.fillStyle = '#FFFFFF'; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(l.label, 0, ph * 0.004); g.restore(); }
    });
    S.nodes.forEach(n => {
      const u = seg(t, n.t0 === undefined ? 0 : n.t0, (n.t0 || 0) + 0.45); if (u <= 0) return; const c = P(n), sc = 0.8 + 0.2 * Math.sin(u * 1.57), lit = n.lit !== undefined && t >= n.lit; g.save(); g.translate(c[0], c[1]); g.scale(sc, sc); g.globalAlpha = u;
      if (n.ico === 'hand' || n.bare) { bdIcon(g, n.ico, 0, 0, ph * 0.13, lit ? '#2B8A6E' : undefined); }
      else { g.shadowColor = 'rgba(11,25,30,0.25)'; g.shadowBlur = ph * 0.02; rrect(g, -NW / 2, -NH / 2, NW, NH, ph * 0.03); g.fillStyle = lit ? '#E6F8EE' : '#FFFFFF'; g.fill(); g.shadowColor = 'transparent'; g.lineWidth = ph * 0.01; g.strokeStyle = lit ? '#2B8A6E' : '#17252B'; g.stroke();
        bdIcon(g, n.ico, 0, -NH * 0.08, ph * 0.095, lit ? '#2B8A6E' : undefined); g.fillStyle = '#17252B'; g.font = '900 ' + ph * 0.042 + 'px' + FAM; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(n.label, 0, NH * 0.38); }
      (n.badge || []).forEach(q => { if (t >= q[0]) { const w = Math.min(1, (t - q[0]) / 0.25); g.save(); g.translate(0, -NH * 0.62); g.scale(0.7 + 0.3 * w, 0.7 + 0.3 * w); g.font = '900 ' + ph * 0.06 + 'px' + FAM; const tw = g.measureText(q[1]).width + ph * 0.12; rrect(g, -tw / 2, -ph * 0.045, tw, ph * 0.09, ph * 0.03); g.fillStyle = '#17252B'; g.fill(); g.fillStyle = '#F2D58F'; g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(q[1], 0, ph * 0.004); g.restore(); } });
      if (n.eye && t >= n.eye[0] && t < n.eye[1]) bdIcon(g, 'eye', NW * 0.34, -NH * 0.52, ph * 0.07);
      if (n.grow && t >= n.grow[0]) { const q = seg(t, n.grow[0], n.grow[1]); g.fillStyle = '#2B8A6E'; for (let i = 0; i < 3; i++) { const h = (0.07 + i * 0.05) * ph * Math.min(1, q * 3 - i * 0.6 + 0.001 > 0 ? Math.min(1, q * 3 - i * 0.6) : 0); g.fillRect(NW * 0.42 + i * ph * 0.035, NH * 0.4 - h, ph * 0.026, h); } }
      g.restore();
    });
  };
'''
i = t.index("  const pad = (x0, z0, x1, z1, col)"); p.write_text(t[:i] + add + t[i:], encoding='utf8'); print('board added')
